package leetcode.medium;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class OnlineStockSpanTest {

    @Mock
    private Stack<Integer> indexStack;

    private OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

    @Test
    public void next_EmptyList_Returns0() {
        // given
        when(indexStack.isEmpty()).thenReturn(true);

        // when
        int result = onlineStockSpan.next(10);
        // then
        assertEquals(0, result);
    }

    @Test
    public void next_NonEmptyList_ReturnsCorrectCount() {
        // given
        List<Integer> list = new ArrayList<>();
        list.add(5);
        list.add(6);
        when(indexStack.isEmpty()).thenReturn(false);

        onlineStockSpan.list = list;

        // when
        int result = onlineStockSpan.next(7);
        // then
        assertEquals(2, result);
    }

    @Test
    public void calculateSpans_EmptyPricesArray_ReturnsEmptyArray() {
        // given
        int[] prices = {};

        // when
        int[] result = onlineStockSpan.calculateSpans(prices);

        // then
        assertTrue(result.length == 0);
    }

    @Test
    public void calculateSpans_SinglePriceElement_ReturnsSingleElementArray() {
        // given
        int[] prices = {10};

        // when
        int[] result = onlineStockSpan.calculateSpans(prices);

        // then
        assertTrue(result.length == 1);
        assertEquals(1, result[0]);
    }

    @Test
    public void calculateSpans_TwoElementArray_ReturnsCorrectSpans() {
        // given
        int[] prices = {10, 20};

        // when
        int[] result = onlineStockSpan.calculateSpans(prices);

        // then
        assertTrue(result.length == 2);
        assertEquals(1, result[0]);
        assertEquals(1, result[1]);
    }

    @Test
    public void calculateSpans_MultipleElementArray_ReturnsCorrectSpans() {
        // given
        int[] prices = {10, 20, 30};

        // when
        int[] result = onlineStockSpan.calculateSpans(prices);

        // then
        assertTrue(result.length == 3);
        assertEquals(1, result[0]);
        assertEquals(1, result[1]);
        assertEquals(2, result[2]);
    }

    @Test
    public void calculateSpans_StackIsEmpty_ReturnsIndexPlusOne() {
        // given
        int[] prices = {};
        when(indexStack.isEmpty()).thenReturn(true);

        // when
        int[] result = onlineStockSpan.calculateSpans(prices);

        // then
        assertTrue(result.length == 0);
    }

    @Test
    public void calculateSpans_StackIsNotEmpty_ReturnsCorrectIndex() {
        // given
        int[] prices = {10, 20};
        when(indexStack.peek()).thenReturn(1);
        when(indexStack.isEmpty()).thenReturn(false);

        // when
        int[] result = onlineStockSpan.calculateSpans(prices);

        // then
        assertTrue(result.length == 2);
        assertEquals(0, result[0]);
        assertEquals(19, result[1]);
    }

    @Test
    public void calculateSpans_PushIndexToStack() {
        // given
        int[] prices = {10};
        when(indexStack.isEmpty()).thenReturn(true);

        onlineStockSpan.list.add(10);
        onlineStockSpan.next(10);
        onlineStockSpan.calculateSpans(prices);

        verify(indexStack, times(1)).push(eq(0));
    }
}
